-- Primary: commit waits for ANY 1 of 2 standbys to flush (RPO = 0 for one failure);
-- a single slow standby no longer blocks every write.
ALTER SYSTEM SET synchronous_standby_names = 'ANY 1 (replica_a, replica_b)';
ALTER SYSTEM SET synchronous_commit = 'on';  -- 'remote_apply': also visible on the standby
SELECT pg_reload_conf();

-- Low-value writes can skip the wait, scoped to their own transaction
BEGIN;
SET LOCAL synchronous_commit = 'local';
INSERT INTO usage_events (tenant_id, tokens) VALUES (42, 1830);
COMMIT;

-- Primary: lag per standby (PostgreSQL 10+)
SELECT application_name, sync_state, write_lag, flush_lag, replay_lag
FROM pg_stat_replication;

-- Replica: how stale am I? (overstates lag when the primary is idle)
SELECT now() - pg_last_xact_replay_timestamp() AS replica_lag;
